<?php

namespace Database\Seeders;

/** Seeds `blog_seo` from database/seeders/data/blog_posts.json (generated by scripts/export-seed-data.ts in the frontend repo). */
class BlogPostsSeeder extends ContentSeederBase
{
    public const TABLE = 'blog_seo';

    public function run(): void
    {
        if (! $this->tableReady(self::TABLE)) {
            return;
        }
        // TABLE: the table behind /api/v1/blog-seo. Change the constant if your table is named differently.
        $images = ['cover_image' => 'blog'];
        $keyCol = $this->hasColumn(self::TABLE, 'slug') ? 'slug' : 'name_ar';

        foreach ($this->json('blog_posts') as $row) {
            if (empty($row[$keyCol])) {
                continue;
            }
            $this->upsertFillEmpty(self::TABLE, [$keyCol => $row[$keyCol]], $row, $images);
        }

        $this->report(self::TABLE);
    }
}
